using UnityEngine;

// Story mode data: four campaigns (Legion, Dynasty, Heralds, Shadow Guild), four acts each, five fights and a boss per act.
// Every text is a dialog: one line per "\n", each line starts with who speaks:
//   N: narrator    P: you    A: your companion    E: this fight's opponent
public class StoryNode
{
    public string title, enemyName, pre, post;
    public Faction enemy;
    public int level, arena, skin = -1;
    public int[] powers;           // bosses: their strange powers (see Fighter.BossPowerNames)
    public bool boss, female;
}

public class StoryAct
{
    public string title, intro, outro;
    public StoryNode[] nodes;
}

public class Campaign
{
    public Faction faction;
    public string title, blurb, ending, ally;
    public Vector2 start;         // where the hero starts on the world map (0..1)
    public Vector2[][] route;     // each act's road on the map: waypoints from the previous act's end
    public StoryAct[] acts;
}

public static class Story
{
    public const int NodesPerAct = 6, Acts = 4, Total = NodesPerAct * Acts;
    static readonly int[] ActLevel = { 2, 7, 12, 17 };
    static readonly int[] ArenaOf = { 0, 1, 2, 3 };   // Legion → Colosseum, Dynasty → temple, Heralds → sanctum, Shadow → crypt

    // centres of the four territories on the world map
    public static readonly Vector2[] Region = { new Vector2(0.17f, 0.52f), new Vector2(0.83f, 0.48f), new Vector2(0.5f, 0.17f), new Vector2(0.5f, 0.8f) };
    public static readonly string[] RegionName = { "ИМПЕРИЯ ЛЕГИОНА", "ЗЕМЛИ ДИНАСТИИ", "НЕБЕСНЫЙ ПРЕДЕЛ ВЕСТНИКОВ", "РАЗЛОМ ТЕНЕЙ" };

    static StoryNode F(string title, string name, Faction f, bool female, string pre, string post)
    {
        return new StoryNode { title = title, enemyName = name, enemy = f, female = female, pre = pre, post = post };
    }

    static StoryNode B(string title, string name, Faction f, bool female, int skin, int[] powers, string pre, string post)
    {
        return new StoryNode { title = title, enemyName = name, enemy = f, female = female, boss = true, skin = skin, powers = powers, pre = pre, post = post };
    }

    static StoryAct A(string title, string intro, string outro, params StoryNode[] nodes)
    {
        return new StoryAct { title = title, intro = intro, outro = outro, nodes = nodes };
    }

    const Faction L = Faction.Legion, D = Faction.Dynasty, H = Faction.Heralds, S = Faction.ShadowGuild;

    public static readonly Campaign[] Campaigns =
    {
        // ======================= LEGION =======================
        new Campaign
        {
            faction = L, title = "Железная клятва", ally = "Опцион Луция", start = new Vector2(0.06f, 0.22f),
            blurb = "Ты легионер пограничного форта. Разлом Теней открылся у южных рубежей Империи, и в его тени зреет измена.",
            ending = "N:Разлом запечатан, Мортус повержен. Легион выбивает твоё имя на воротах Колизея.\nA:Клятва исполнена, легионер. Щит к щиту — до конца.",
            route = new[]
            {
                new[] { new Vector2(0.2f, 0.14f), new Vector2(0.3f, 0.3f), new Vector2(0.16f, 0.42f), new Vector2(0.08f, 0.6f), new Vector2(0.22f, 0.72f) },
                new[] { new Vector2(0.3f, 0.88f), new Vector2(0.45f, 0.93f), new Vector2(0.62f, 0.9f), new Vector2(0.76f, 0.8f), new Vector2(0.86f, 0.66f) },
                new[] { new Vector2(0.94f, 0.5f), new Vector2(0.86f, 0.34f), new Vector2(0.9f, 0.16f), new Vector2(0.74f, 0.1f), new Vector2(0.6f, 0.2f) },
                new[] { new Vector2(0.48f, 0.12f), new Vector2(0.36f, 0.24f), new Vector2(0.44f, 0.38f), new Vector2(0.58f, 0.46f), new Vector2(0.5f, 0.68f) },
            },
            acts = new[]
            {
                A("Пепел на границе",
                  "N:Из пограничного форта Кастра Ферра перестали приходить гонцы. Командование отправляет тебя выяснить, что случилось.\nA:Три дня тишины. Кастра Ферра никогда так не молчала.\nP:Значит, пора узнать почему. Держись рядом, Луция.\nA:Как в старые времена. Щит к щиту.",
                  "N:Легион выступает на восток, к Нефритовой стене.\nA:Если Ключ у Династии, они просто так его не отдадут.\nP:Тогда поговорим на их языке.",
                  F("Сожжённая застава", "Разведчик Теней", S, false,
                    "N:Застава горит, а среди дыма мелькает фигура в чёрном. Разведчик Гильдии Теней добивает раненых.\nA:Смотри! Он в чёрном, это не наш.\nE:Ещё один легионер. Хозяин будет доволен: чем больше мёртвых, тем шире Разлом.\nP:Какой ещё хозяин?\nE:Скоро узнаешь. Если доживёшь.",
                    "E:Поздно... ворота уже открыты...\nA:Какие ворота? Он о форте?\nP:Идём к мосту. Там короче."),
                  F("Дезертир", "Дезертир Гай", L, false,
                    "N:У моста тебя встречает легионер со споротыми знаками.\nE:Стой. Дальше дороги нет.\nA:Гай? Ты же служил в Кастра Ферра!\nE:Служил. Пока ночью ворота не открылись сами. Тени вошли как домой. Легион нас бросил.\nP:Легион никого не бросает. Опусти меч.\nE:Не опущу. Никто туда не пойдёт. Там смерть.",
                    "E:Хорошо бьёшь... Слушай. Ворота открыл кто-то изнутри. Кто-то из офицеров.\nA:Изнутри? Это измена.\nP:Разберёмся. Гай, иди в лагерь и расскажи всё легату.\nE:Иду. И... прости."),
                  F("Чужой следопыт", "Следопыт Мэй", D, true,
                    "N:В лесу ты замечаешь лазутчицу Династии. Она идёт по тому же следу.\nE:Легионеры. Шумите как стадо быков.\nA:Что Династия забыла на нашей земле?\nE:То же, что и вы: след Теней. Они украли кое-что у нас. И этот след мой.\nP:Здесь земля Империи. Уходи.\nE:Уйду, когда проиграю. То есть никогда.",
                    "E:Ладно... ты сильнее, чем кажешься. Скажу одно: у вашего центуриона на поясе знак Гильдии. Я видела сама.\nA:У Марка? Не может быть...\nP:Сейчас проверим."),
                  F("Мародёры", "Мародёр Фабий", L, false,
                    "N:В разорённой деревне хозяйничают мародёры в легионерских плащах.\nA:Это же наши плащи! Кто дал им право грабить?\nE:Форт пал, центурион сказал — берите что хотите. Мы и берём.\nP:Центурион Марк? Он жив?\nE:Живее тебя. Проваливай, пока цел.",
                    "E:Марк... в форте... он открыл ворота... сам...\nA:Ложь! Марк не мог.\nP:Скоро узнаем."),
                  F("Ошейник Разлома", "Зверолов Теней", S, false,
                    "N:У стен форта бродит человек с ошейником Разлома на шее. Он рычит как зверь.\nE:Р-р-разлом... голоден...\nA:Что с ним сделали?\nP:То же, что сделают со всеми, если мы не остановим это.",
                    "N:Ошейник трескается и рассыпается пеплом. Человек затихает.\nA:Он дышит. Мы его спасли.\nP:Одного. Впереди ворота форта."),
                  B("Предатель у ворот", "Центурион Марк", L, false, 5, new[] { 0, 7 },
                    "N:Ворота форта открыты изнутри. Во дворе стоит центурион Марк, твой бывший командир. Его глаза горят багровым.\nA:Центурион! Вы живы!\nE:Жив? Я больше чем жив, Луция. Разлом дал мне силу, о которой Легион и не мечтал.\nP:Это вы открыли ворота.\nE:Я открыл их будущему. Империя прогнила. Тени построят новый порядок.\nP:Вы сами учили: клятва Легиона крепче железа.\nE:Тогда проверим, крепка ли твоя. Я учил тебя всему. Но не всему научил.",
                    "E:Ключ... от Разлома... у Династии... они не удержат его...\nA:Он мёртв. Наш центурион... мёртв.\nP:Наш центурион погиб в ту ночь, когда открыл ворота. Это была лишь тень.")),
                A("Нефритовая стена",
                  "N:Легион подходит к Нефритовой стене. Династия закрыла ворота и не желает слушать чужеземцев.\nA:Стены до неба. Штурмом не взять.\nP:Нам не нужен штурм. Нужен разговор с генералом.\nA:С Династией разговор один: через поединок.",
                  "N:Генерал даёт вам проводника до небесной лестницы.\nE:Вестники горды. Они не слушают тех, кто живёт на земле.\nP:Значит, придётся подняться к ним.",
                  F("Стража ворот", "Страж Нефритовых врат", D, false,
                    "N:У ворот стоит страж в нефритовых доспехах.\nE:Ни один легионер не пройдёт через врата живым.\nP:Мы пришли говорить, а не воевать.\nE:В прошлый раз Легион тоже пришёл говорить. Мы до сих пор хороним павших.\nA:Тогда была другая война.\nE:Для Династии война всегда одна.",
                    "E:Ты бьёшься с честью. Проходи... но генерал не будет так любезен.\nP:Посмотрим."),
                  F("Монах с горной тропы", "Монах Цин", D, false,
                    "N:На горной тропе, под старой сосной, сидит монах.\nE:Горы не любят спешки. Куда ты так торопишься, воин Империи?\nP:К генералу Ли Шэню. Над миром нависла тьма.\nE:Тьма нависает всегда. Вопрос лишь в том, светит ли что-то в тебе.\nA:Опять загадки...\nE:Одолей меня в честном бою, и я укажу короткий путь.",
                    "E:В тебе есть свет. Мало, но есть. Иди вдоль ручья, и выйдешь к лагерю генерала.\nP:Спасибо, мастер.\nE:Благодари не меня. Благодари того, кто тебя учил."),
                  F("Рисовые поля", "Крестьянин-воин Бо", D, false,
                    "N:На рисовых полях крестьяне Династии встречают легионеров с серпами и копьями.\nE:Легион сжёг мою деревню двадцать лет назад. Второй раз не позволю!\nA:Мы здесь не за этим!\nE:Вы всегда здесь не за этим.",
                    "E:Легионер пощадил крестьянина? Такого я ещё не видел.\nP:Мы воюем с Тенями, а не с крестьянами.\nE:Тогда иди. Лагерь генерала за рисовыми полями."),
                  F("Небесные фонари", "Ученица фонарей Юэ", D, true,
                    "N:Ночью над лагерем взлетают фонари. Под одним из них ждёт девушка с парными клинками.\nE:Фонари указывают путь только достойным. Остальных они сжигают.\nP:Покажи путь.\nE:Сначала покажи, что ты достоин.",
                    "E:Фонарь горит ровно... Значит, ты говоришь правду.\nA:Даже фонари здесь проверяют.\nE:Генерал Ли Шэнь в шатре за рекой. Берегитесь убийц."),
                  F("Тень среди своих", "Убийца Лин", S, true,
                    "N:Ночью в лагере Династии мелькает тень. Кто-то крадётся к шатру генерала.\nA:Там! У шатра!\nE:Тише, легионер. Если генерал умрёт, Династия решит, что это сделали вы. Война, которую хочет Гильдия, начнётся сама.\nP:Не начнётся. Я не дам.\nE:Ты? Одна маленькая свеча против ночи?",
                    "E:Хозяин... всё равно... получит Ключ...\nA:Опять этот Хозяин. Кто он?\nP:Потом. Сначала генерал."),
                  B("Совет генерала", "Генерал Ли Шэнь", D, false, 2, new[] { 3, 4 },
                    "N:Генерал Ли Шэнь выходит из шатра. Рядом лежит убийца Гильдии.\nE:Легионер спасает мне жизнь. Или разыграл спектакль, чтобы войти в доверие.\nP:Мне не нужно ваше доверие. Мне нужен Ключ от Разлома.\nE:Ключ! Так вот зачем вы пришли. Как и Тени.\nA:Генерал, мы сражаемся с Тенями!\nE:Слова ничего не стоят. Докажи клинком, что ты не слуга Теней. Три победы, как велит обычай.",
                    "E:Довольно. Слуга Теней не бился бы так чисто.\nP:Теперь вы верите?\nE:Верю. Но есть беда: Ключа у меня нет. Он хранился в моём храме, и его забрали Вестники. Они хотят запечатать Разлом по-своему.\nA:Вестники... значит, в небо.")),
                A("Свет с небес",
                  "N:Путь ведёт к Небесному святилищу, над облаками.\nA:Никогда не думала, что увижу облака сверху.\nP:Смотри под ноги. Лестница длинная.\nA:Говорят, Вестники уверены, что только они вправе решать судьбу мира.",
                  "N:Серафина отдаёт Ключ. Над святилищем трубят рога: Вестники собираются в поход.\nA:Легион, Династия и Вестники вместе. Мортус такого не ждёт.\nP:Пусть ждёт. Мы уже идём.",
                  F("Небесный дозор", "Дозорный Вестников", H, false,
                    "N:На лестнице к святилищу тебя встречает дозорный в белых доспехах.\nE:Стой, земной. Небесный предел закрыт для чужаков.\nP:Мы пришли за Ключом от Разлома.\nE:Ключ в руках тех, кто достоин. Легион к ним не относится.\nA:А кто решает, кто достоин?\nE:Свет. И мой клинок.",
                    "E:Свет... не отвернулся от тебя. Странно. Проходи.\nP:Где Ключ?\nE:Спроси жрицу Элею. Если она тебя выслушает."),
                  F("Испытание света", "Жрица Элея", H, true,
                    "N:У фонтана света стоит жрица в серебряной накидке.\nE:Я видела тебя во сне, воин. Ты несёшь тьму на плечах.\nP:Я несу вести о тьме. Это разное.\nE:Возможно. Выстоишь против меня, и я поверю. Упадёшь — вернёшься вниз.\nA:Хоть кто-то говорит прямо.",
                    "E:Тьмы в тебе нет. Только усталость. Отдохни у фонтана.\nP:Некогда отдыхать. Где Ключ?\nE:На алтаре. Но в святилище кто-то чужой, я это чувствую."),
                  F("Облачный мост", "Страж облачного моста", H, false,
                    "N:Между двумя вершинами натянут мост из облаков. На нём стоит страж с копьём света.\nE:Облака держат лишь лёгких сердцем. Тяжёлых — сбрасывают.\nA:Легионер в доспехах... лёгкий сердцем?\nP:Посмотрим.",
                    "E:Твоё сердце тяжело от потерь, но не от лжи. Облака тебя выдержат.\nA:Только не смотри вниз."),
                  F("Библиотека света", "Хранительница свитков Ила", H, true,
                    "N:В библиотеке святилища хранительница свитков преграждает путь к алтарю.\nE:Здесь записано всё о Разломе. И нигде не сказано, что Легион должен его закрыть.\nP:Значит, пора дописать главу.\nE:Дерзко. Перо — это клинок. Покажи, как ты пишешь.",
                    "E:Хорошо. Я впишу твоё имя... карандашом. Пока.\nE:Поторопись к алтарю. Сегодня там слишком тихо."),
                  F("Шпион в белом", "Шпион Теней", S, false,
                    "N:У алтаря вестник в белом тянется к Ключу. Под капюшоном блестят чёрные глаза.\nA:Он не вестник! Смотри на глаза!\nE:Ну вот, раскрыли. Жаль. Мог бы уйти тихо.\nP:Положи Ключ на место.\nE:Хозяин ждёт его. А Хозяин не любит ждать.",
                    "E:Серафина... тоже... не верит тебе... ха-ха...\nA:Он пытается нас поссорить с Вестниками.\nP:Похоже, у него и так получилось. Слышишь шаги?"),
                  B("Суд Серафины", "Вестница Серафина", H, true, 3, new[] { 1, 2 },
                    "N:В зал входит верховная вестница Серафина. Свет вокруг неё слепит.\nE:Легионер у алтаря. Шпион Теней на полу. Кто из вас пришёл за Ключом?\nP:Я его защищал.\nE:Так говорят все воры. Легион сжигал наши храмы сто лет назад. Я не забыла.\nA:Это было сто лет назад!\nE:Свет помнит всё. Мой клинок не знает промаха. Покажи, чего стоит твоя правда.",
                    "E:Твой клинок был у моего горла. И всё же я жива. Почему?\nP:Нам нужен союзник, а не ещё один мёртвый.\nE:Вот теперь я верю. Возьми Ключ. Запечатаем Разлом вместе. Но сперва одолей того, кто его открыл.\nA:Кто он?\nE:Владыка Теней Мортус. Хозяин Гильдии. Он ждёт в жерле вулкана.")),
                A("Сердце Разлома",
                  "N:Три фракции впервые стоят плечом к плечу. Впереди вулкан, в жерле которого пульсирует Разлом.\nA:Сколько их там... Вся Гильдия собралась.\nP:Тем лучше. Не придётся искать по одному.\nA:Если не вернёмся... я рада, что шла с тобой.",
                  "N:Мортус пал, и Ключ запечатал Разлом.\nA:Домой?\nP:Домой. Нас ждёт Колизей.",
                  F("Авангард Теней", "Страж Разлома", S, false,
                    "N:У подножия вулкана стоит страж Разлома в костяной маске.\nE:Живые. Как давно я не видел живых.\nP:Отойди с дороги.\nE:Я и есть дорога. Каждый, кто прошёл через меня, остался здесь навсегда.",
                    "E:Ты... первый... кто прошёл...\nA:Вперёд, пока они не сомкнули строй!"),
                  F("Одержимый трибун", "Трибун Север", L, false,
                    "N:Среди Теней ты узнаёшь трибуна Легиона. Его доспех почернел.\nA:Трибун Север! Мы думали, вы погибли на юге!\nE:Север умер. Осталось то, что слышит голос Разлома.\nP:Трибун, вспомните клятву!\nE:Клятва... Какое глупое слово. Разлом шепчет слаще.",
                    "E:Клятва... я помню... спасибо, легионер...\nA:Он ушёл свободным.\nP:Мортус заплатит за каждого из них."),
                  F("Лавовые копи", "Надсмотрщик копей", S, false,
                    "N:В лавовых копях Гильдия заставляет пленников добывать чёрный камень для Разлома.\nE:Работать! Кто остановится — в лаву!\nA:Там легионеры! Наши пленные!\nP:Освобождаем.",
                    "N:Пленники сбрасывают цепи и поднимают кирки.\nA:Легион! Строиться! Они идут с нами!\nP:Теперь нас больше."),
                  F("Двойник", "Тень легионера", S, false,
                    "N:Из дыма выходит воин в твоих доспехах и с твоим лицом.\nE:Я — это ты, только честнее. Я не притворяюсь, что мне не страшно.\nP:Мне страшно. Но я иду дальше.\nA:Не слушай его! Это морок Разлома!",
                    "E:Страх... не остановил... тебя...\nN:Двойник тает, как дым.\nA:Ты в порядке?\nP:В полном. Вперёд."),
                  F("Правая рука", "Жнец Нокс", S, true,
                    "N:На краю жерла стоит жнец Нокс, правая рука владыки Теней.\nE:Марк пал. Шпион пал. Север пал. И всё из-за одного легионера.\nP:Из-за вас. Вы начали эту войну.\nE:Мы её и закончим. Владыка не должен тебя увидеть. Это я тебе обещаю.\nA:Иди! Я прикрою сзади!",
                    "E:Владыка... тебя... сожрёт...\nP:Луция?\nA:Я здесь! Держу строй! Иди к жерлу, только ты сможешь!"),
                  B("Владыка Разлома", "Владыка Теней Мортус", S, false, 5, new[] { 5, 6, 7, 0 },
                    "N:В сердце вулкана, над пульсирующим Разломом, ждёт Мортус.\nE:Легионер. Одиночка против вечности. Как трогательно.\nP:Не одиночка. За мной три фракции.\nE:И все они падут, когда Разлом раскроется полностью. Марк был слаб. Север был слаб. Но в тебе я вижу силу. Встань рядом со мной.\nP:Я уже стою. В строю Легиона.\nE:Тогда умри как легионер.",
                    "E:Невозможно... Разлом... был... моим...\nN:Ключ вспыхивает в твоей руке, и трещина в земле с грохотом смыкается.\nA:Получилось! Разлом закрывается!")),
            },
