            {
                new[] { new Vector2(0.62f, 0.12f), new Vector2(0.7f, 0.26f), new Vector2(0.56f, 0.36f), new Vector2(0.42f, 0.3f), new Vector2(0.3f, 0.16f) },
                new[] { new Vector2(0.18f, 0.26f), new Vector2(0.08f, 0.42f), new Vector2(0.2f, 0.56f), new Vector2(0.1f, 0.72f), new Vector2(0.24f, 0.84f) },
                new[] { new Vector2(0.38f, 0.93f), new Vector2(0.56f, 0.94f), new Vector2(0.72f, 0.86f), new Vector2(0.86f, 0.72f), new Vector2(0.9f, 0.5f) },
                new[] { new Vector2(0.88f, 0.32f), new Vector2(0.76f, 0.42f), new Vector2(0.64f, 0.52f), new Vector2(0.56f, 0.6f), new Vector2(0.5f, 0.68f) },
            },
            acts = new[]
            {
                A("Падший брат",
                  "N:Алтарь Небесного святилища осквернён. Следы ведут к брату Азраилу, лучшему из вестников.\nA:Азраил учил тебя держать клинок. Теперь тебе придётся поднять клинок против него.\nP:Может, это ошибка. Может, его подставили.\nA:Хотела бы я в это верить.",
                  "A:Мы заберём его в святилище. Может быть, свет его вылечит.\nP:А мне дорога на запад, в земли Легиона.\nA:Будь осторожнее. Легион не любит нас.",
                  F("Осквернённый алтарь", "Осквернитель", S, false,
                    "N:У алтаря ещё стоит тот, кто его осквернил, воин Гильдии Теней.\nE:Свет погас. Чувствуешь? Холодно.\nP:Кто тебя впустил?\nE:Твой брат. Азраил открыл двери и сказал: «Добро пожаловать».",
                    "E:Азраил... уже не ваш... он наш...\nA:Ложь. Это должна быть ложь."),
                  F("Сомневающийся", "Послушник Тит", H, false,
                    "N:Во дворе святилища послушник Тит собирает сторонников Азраила.\nE:Азраил прав! Вестники веками прятали свет от мира!\nP:Тит, он открыл двери Теням.\nE:Тени — просто другая сторона света. Так он сказал.\nA:Азраил сказал бы что угодно, лишь бы ему поверили.",
                    "E:Я... я не знаю, во что верить...\nP:Верь тому, что видишь. Алтарь в крови.\nE:Азраил ушёл к Каменному мосту. Там его ищет охотница Династии."),
                  F("Чёрные перья", "Осквернённый страж", H, false,
                    "N:На тропе к мосту лежат чёрные перья. Над ними стоит страж с потухшими глазами.\nE:Азраил сказал... никого не пускать...\nP:Азраил больше не командует стражей.\nE:Азраил... командует... всем...",
                    "E:Свет... вернулся... Где я?\nA:Дома, брат. Отдыхай."),
                  F("Горная обитель", "Отшельница Мира", H, true,
                    "N:В горной обители живёт отшельница, что когда-то учила Азраила.\nE:Я знаю, зачем ты здесь. Ты хочешь убить его.\nP:Я хочу его вернуть.\nE:Тогда тебе нужно быть сильнее его. Проверим.",
                    "E:Хватит. Может, у тебя и получится.\nE:Помни: тьма в нём боится воды. У водопада он слабее всего."),
                  F("Охотница", "Охотница Сяо", D, true,
                    "N:У Каменного моста охотница Династии снимает лук и берётся за клинок.\nE:Вестник. За голову Азраила обещано сто золотых драконов. Не мешай.\nP:Азраил — наш брат. Мы сами его найдём.\nE:Тогда сначала уложи меня на землю.",
                    "E:Ладно... твой брат, тебе и решать. Он у водопада. И он... очень изменился.\nA:Готовься. Он будет не тем, кого ты помнишь."),
                  B("Павший вестник", "Падший вестник Азраил", H, false, 4, new[] { 2, 7 },
                    "N:У водопада стоит Азраил. Его крылья чёрные, глаза пусты.\nE:Я знал, что пошлют именно тебя. Лучший ученик.\nP:Азраил, остановись. Вернись домой.\nE:Дома нет. Есть только Разлом и то, что за ним. Там такая сила...\nA:Азраил, это не ты говоришь. Это тьма.\nE:Тьма честнее света, Аурея. Она не прячет правду.",
                    "E:Больно... Свет... Я вижу...\nE:Тьма идёт из земель Легиона. Там кто-то... поёт... Прости меня.\nN:Азраил теряет сознание. Тьма отступает, но не уходит.")),
                A("Железный марш",
                  "N:Легион собирает войско, чтобы сжечь святилище: они верят, что Разлом открыли Вестники.\nA:Весть о падении Азраила дошла до Легиона. Теперь они думают, что во всём виноваты мы.\nP:Значит, надо остановить войну раньше, чем она начнётся.",
                  "N:Легион разворачивает войско. Война отменена, но туман над миром сгущается.\nA:Я получила твоё послание. Туман на востоке не природный. Будь осторожнее.\nP:Буду.",
                  F("Передовой отряд", "Легионер-разведчик", L, false,
                    "N:Передовой отряд Легиона уже у подножия небесной лестницы.\nE:Смотрите, вестник! Один, без крыльев!\nP:Я здесь, чтобы говорить.\nE:Говорить будешь с легатом. В цепях.",
                    "E:Нам говорили, что вестники трусы...\nP:Вам много чего говорили."),
                  F("Знаменосец", "Знаменосец Тиберий", L, false,
                    "N:Знаменосец ведёт легионеров в бой.\nE:За Империю! За легата! Смерть крылатым!\nP:Тиберий! Вестники не открывали Разлом!\nE:Скажи это сожжённой Кастра Ферра!",
                    "N:Знамя падает в пыль. Строй легионеров замирает.\nE:Если не вы... то кто?\nP:Это и надо выяснить. Вместе."),
                  F("Осадные машины", "Инженер Марций", L, false,
                    "N:Легионеры собирают катапульты, нацеленные на святилище.\nE:Ещё день, и ваше гнездо полетит вниз камнями!\nP:Вы целитесь не туда!\nE:Я целюсь, куда приказано.",
                    "N:Катапульта трещит и разваливается.\nE:Ладно... без неё штурм подождёт...\nA:Весть из святилища: держись. Мы молимся за тебя."),
                  F("Ветеран", "Ветеран Корнелия", L, true,
                    "N:Старая легионерка сидит у костра и точит меч.\nE:Тридцать лет в Легионе. Видела много вестников. Все — лжецы.\nP:Значит, пора увидеть исключение.\nE:Острый язык. Посмотрим, так же ли остёр меч.",
                    "E:Хм. Может, и не все лжецы. Иди к обозу. Там по ночам творится неладное."),
                  F("Тень в обозе", "Поджигатель Теней", S, false,
                    "N:Ночью в обозе Легиона вспыхивают шатры. У огня стоит человек в чёрном.\nE:Горит красиво, правда? Утром легионеры решат, что это сделали вестники.\nP:Так вот кто разжигает войну.\nE:Мы только подливаем масло. Остальное вы сделали сами.",
                    "E:Легат... всё равно... не поверит...\nP:Поверит, когда увидит тебя."),
                  B("Легат", "Легат Валерия", L, true, 2, new[] { 0, 6 },
                    "N:Легат Валерия выходит к тебе с обнажённым мечом. У её ног — связанный поджигатель.\nE:Шпион Гильдии в моём обозе. И вестник, который его поймал. Удобно.\nP:Это правда, легат. Нас стравливают.\nE:Может быть. А может, вы с Гильдией разыграли это вместе.\nP:Что нужно, чтобы вы поверили?\nE:Бой. Легион верит только мечу. Остановишь меня — остановишь войну.",
                    "E:Хватит. Я видела достаточно.\nE:Раз не вы открыли Разлом, то кто?\nP:Не знаю. Но Азраил сказал, что тьма поёт.\nE:Мудрец Бай Лун в землях Династии слышит всё, что поёт в этом мире. Иди к нему.")),
                A("Туман над Нефритом",
                  "N:В землях Династии сгущается туман. Мудрец Бай Лун знает, кто открыл Разлом, но молчит.\nA:Азраил очнулся. Он повторяет одно слово: «Первый».\nP:Первый кто?\nA:Не знаю. Спроси мудреца.",
                  "N:Бай Лун отдаёт тебе древний амулет рассвета.\nA:Я иду с тобой. И Азраил тоже. Он хочет искупить вину.\nP:Тогда идём все вместе.",
                  F("Туманная тропа", "Страж тумана", D, false,
                    "N:На туманной тропе тебя встречает страж.\nE:Назови цель пути.\nP:Мудрец Бай Лун.\nE:К мудрецу ходят многие. Возвращаются немногие. Докажи, что туман тебя не проглотит.",
                    "E:Туман тебя не проглотил. Иди. Мастер Фэн встретит у ворот."),
                  F("Мастер нунчак", "Мастер Фэн", D, false,
                    "N:Мастер Фэн вращает нунчаки так быстро, что они свистят.\nE:Гость мудреца должен быть быстрее ветра. Ты быстрее ветра?\nP:Проверь.\nE:С удовольствием!",
                    "E:Хо! Быстро! Очень быстро. Мудрец примет тебя. Но сначала поговори с послом. Он любит гостей... слишком любит."),
                  F("Пруд карпов", "Рыбак-мастер Лэй", D, false,
                    "N:У пруда рыбак ловит рыбу... голыми руками.\nE:Карпы быстрые. Ты быстрее карпа?\nP:С рыбой соревноваться не доводилось.\nE:Тогда начнём с меня.",
                    "E:Быстрее карпа! Мудрец будет доволен."),
                  F("Хранительница свитков", "Хранительница Мин", D, true,
                    "N:В библиотеке мудреца хранительница сдувает пыль со свитков, не глядя на тебя.\nE:Здесь все ищут ответы. Мало кто готов к ним.\nP:Я выдержу любой ответ.\nE:Выдержи сначала вопрос. Он будет задан клинком.",
                    "E:Выдержано. Мудрец в саду. Но посол при дворе... берегись его сладких речей."),
                  F("Лживый посол", "Посол Теней", S, false,
                    "N:Посол в богатых одеждах встречает тебя улыбкой.\nE:Вестник! Какая честь. Мудрец занят, но я с радостью всё передам.\nP:От тебя пахнет серой. Как от Разлома.\nE:Ах. Нюх вестников. Как неудобно.",
                    "E:Первый... проснулся... вы все... опоздали...\nP:Опять «Первый». Мне нужен мудрец."),
                  B("Мудрец", "Мудрец Бай Лун", D, false, 2, new[] { 3, 1 },
                    "N:Мудрец Бай Лун сидит у пруда, где плавают золотые карпы.\nE:Посол был шпионом. Я знал. Мне было интересно, заметишь ли ты.\nP:Вы знаете, кто открыл Разлом. Скажите.\nE:Знание — тяжёлая ноша. Вестники несут её плохо. Азраил тому пример.\nP:Тогда отдайте её мне.\nE:Возьми. Если сможешь.",
                    "E:Ты сильнее своего брата. Слушай же.\nE:Разлом открыл Первый из Теней. Древний дух, что был до всех фракций. Он ждёт в жерле вулкана.\nP:Как его победить?\nE:Как побеждают ночь. Дождаться рассвета. Или принести его с собой.")),
                A("Затмение",
                  "N:Солнце гаснет. Первый из Теней выходит из Разлома, и наступает вечная ночь.\nA:Легион, Династия, Вестники — все идут к вулкану. Впервые за тысячу лет.\nP:А где Азраил?\nA:Впереди. Он сказал, что должен встретить свою тень первым.",
                  "N:Первый из Теней рассыпается пеплом.\nA:Смотри. Солнце встаёт.\nP:Последний рассвет... оказался не последним.",
                  F("Порождения тьмы", "Порождение тьмы", S, false,
                    "N:Из трещин в земле лезут порождения тьмы.\nE:Сссвет... гасссить...\nP:С дороги!",
                    "A:Их всё больше! Пробивайся к вулкану, мы задержим остальных!"),
                  F("Тень Азраила", "Тень Азраила", S, false,
                    "N:На тропе стоит Азраил... или то, что носит его лицо.\nE:Это я. Твой брат. Опусти клинок.\nP:Азраил впереди, с армией. Ты не он.\nE:Я его тьма. Всё, что он отдал Разлому. И я сильнее его.",
                    "N:Тень рассыпается чёрными перьями.\nA:Азраил кричит, что видит жерло! Вперёд!"),
                  F("Мёртвый лес", "Лесной призрак", S, true,
                    "N:Лес у вулкана мёртв. Между чёрных деревьев парит призрак с пустыми глазами.\nE:Здесь было светло... до него...\nP:До Первого?\nE:Он выпил свет... выпьет и тебя...",
                    "E:Свет... вернулся... спасибо...\nA:Даже мёртвые ждут рассвета."),
                  F("Обсидиановые врата", "Страж Первого", S, false,
                    "N:У врат жерла стоит страж, выточенный из обсидиана.\nE:Первый спит... Первый проснётся... Первый голоден...\nA:Азраил уже прошёл! Он ждёт тебя у жерла!\nP:Отойди с дороги.",
                    "N:Обсидиан трескается, и врата открываются.\nA:Там, внутри... Никс. А за ней — Он."),
                  F("Хранительница затмения", "Хранительница Никс", S, true,
                    "N:Хранительница затмения стоит у самого жерла, окутанная чёрным солнцем.\nE:Ещё шаг, и ты увидишь Первого. Никто не видел его и не сохранил рассудок.\nP:Мой брат видел и вернулся.\nE:Твой брат вернулся сломанным. Ты вернёшься пылью.",
                    "E:Рассвет... у тебя в руке... как...\nN:Амулет в твоей руке теплеет. Внизу, в жерле, что-то огромное открывает глаза."),
                  B("Первый из Теней", "Первый из Теней", S, false, 5, new[] { 5, 6, 7, 2 },
                    "N:Из Разлома поднимается Первый из Теней. Он старше всех фракций.\nE:Маленький огонёк. Я видел, как гасли тысячи таких.\nP:Этот не погаснет.\nE:Свет, железо, нефрит — всё выросло из тьмы и в неё вернётся. Ты тоже.\nA:Вместе! Все вместе, за рассвет!\nE:Пусть будет так. Последний бой.",
                    "E:Рассвет... я... помню... его...\nN:Амулет вспыхивает, и первый луч солнца пронзает тьму.")),
            },
        },

        // ======================= SHADOW GUILD =======================
        new Campaign
        {
            faction = S, title = "Клинок во тьме", ally = "Сестра Вейла", start = new Vector2(0.72f, 0.93f),
            blurb = "Ты клинок Гильдии Теней. На твоих глазах Хозяин бросает в Разлом собственных учеников. Пора предать тех, кто предал всех.",
            ending = "N:Гильдии больше нет. Вы с Вейлой ведёте спасённых учеников туда, где можно жить без масок.\nA:Знаешь, что самое странное? Мне больше не страшно.",
            route = new[]
            {
                new[] { new Vector2(0.64f, 0.82f), new Vector2(0.54f, 0.9f), new Vector2(0.46f, 0.8f), new Vector2(0.38f, 0.9f), new Vector2(0.34f, 0.78f) },
                new[] { new Vector2(0.22f, 0.7f), new Vector2(0.1f, 0.55f), new Vector2(0.2f, 0.4f), new Vector2(0.1f, 0.24f), new Vector2(0.26f, 0.14f) },
                new[] { new Vector2(0.45f, 0.12f), new Vector2(0.65f, 0.1f), new Vector2(0.82f, 0.18f), new Vector2(0.92f, 0.36f), new Vector2(0.84f, 0.52f) },
                new[] { new Vector2(0.78f, 0.66f), new Vector2(0.68f, 0.58f), new Vector2(0.6f, 0.46f), new Vector2(0.46f, 0.42f), new Vector2(0.5f, 0.62f) },
            },
            acts = new[]
            {
                A("Клеймо предателя",
                  "N:Ты — клинок Гильдии Теней. Двадцать лет ты убиваешь по приказу, не задавая вопросов.\nN:Но этой ночью на твоих глазах Хозяин Некрос бросает в Разлом своих же учеников. Живыми.\nA:Ты тоже это видишь? Значит, я не сошла с ума.\nP:Он кормит Разлом нашими. Надо уходить, Вейла.\nA:Из Гильдии не уходят. Из Гильдии уносят.",
                  "P:Легион. Некрос боится их больше всех. Если они узнают правду, они ударят по Разлому.\nA:Легионеры убьют нас раньше, чем мы откроем рот.\nP:Значит, придётся говорить быстро.",
                  F("Сторож склепа", "Сторож склепа", S, false,
                    "N:У выхода из подземного склепа стоит сторож.\nE:Ночью никто не выходит. Приказ Хозяина.\nP:Хозяин отдаёт много приказов. Этот я не услышу.\nE:Тогда услышишь мой клинок.",
                    "E:Хозяин... найдёт... тебя...\nA:Уже ищет. Бежим, пока не подняли тревогу."),
                  F("Сестра по клинку", "Ассасин Рэн", S, true,
                    "N:В туннеле вас нагоняет Рэн, с которой вы вместе прошли посвящение.\nE:Двое беглецов. Хозяин назначил за вас хорошую цену.\nA:Рэн, он скармливает Разлому учеников! Ты можешь быть следующей!\nE:Значит, надо быть полезной. Ваши головы очень полезны.",
                    "E:Я... не знала... про учеников...\nP:Теперь знаешь. Уходи из Гильдии, пока можешь.\nE:Уйду... если выживу."),
                  F("Кельи учеников", "Надзирательница Мора", S, true,
                    "N:В кельях учеников надзирательница проверяет цепи на дверях.\nE:Беглецы! Хозяин предупреждал. Ученики, смотрите, что бывает с предателями!\nA:Ученики! Бегите за нами! Хозяин скормит вас Разлому!\nE:Молчать!",
                    "N:Ученики переглядываются. Несколько детей срываются с места и бегут к выходу.\nA:Они свободны! Хоть кто-то.\nP:Идём. Их нужно вывести."),
                  F("Зал масок", "Безликий", S, false,
                    "N:В зале масок висят лица тех, кто служил Гильдии. Одна маска вдруг поворачивается к тебе.\nE:Твоя маска давно готова. Висит рядом с моей.\nP:Пусть висит пустой.\nE:Никто не уходит без маски.",
                    "E:Лицо... у меня... было лицо...\nA:Не смотри на маски. Смотри вперёд."),
                  F("Мост костей", "Костяной страж", S, false,
