    static Story()
    {
        // fill in the levels and arenas from the node's place in the campaign
        foreach (var c in Campaigns)
            for (int a = 0; a < Acts; a++)
                for (int i = 0; i < NodesPerAct; i++)
                {
                    StoryNode n = c.acts[a].nodes[i];
                    n.level = ActLevel[a] + i + (n.boss ? 2 : 0);
                    n.arena = (a == Acts - 1 && n.boss) ? 4 : ArenaOf[(int)n.enemy];
                }
    }

    public static StoryNode Node(int c, int idx) { return Campaigns[c].acts[idx / NodesPerAct].nodes[idx % NodesPerAct]; }

    // position of a node on the world map (0..1): the act's fights are spread evenly along its road
    public static Vector2 NodePos(int c, int idx)
    {
        Campaign cp = Campaigns[c];
        int a = idx / NodesPerAct, i = idx % NodesPerAct;
        Vector2[] w = cp.route[a];
        Vector2 prev = a == 0 ? cp.start : cp.route[a - 1][cp.route[a - 1].Length - 1];
        const float aspect = 1.78f;   // the map is wide: measure distances as they look on screen
        float total = 0f;
        Vector2 p = prev;
        foreach (var q in w) { total += Vector2.Distance(new Vector2(p.x * aspect, p.y), new Vector2(q.x * aspect, q.y)); p = q; }
        float want = total * (i + 1) / NodesPerAct;
        p = prev;
        foreach (var q in w)
        {
            float len = Vector2.Distance(new Vector2(p.x * aspect, p.y), new Vector2(q.x * aspect, q.y));
            if (want <= len + 1e-4f) return Vector2.Lerp(p, q, len > 0f ? want / len : 1f);
            want -= len;
            p = q;
        }
        return w[w.Length - 1];
    }
}
